from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'sprint-helper.js').read_text()
helpers=s[s.index('function parsePoints('):s.index('// Helper: Check if card title')]+s[s.index('function s4tIsCommonCard('):s.index('function s4tIsCommonCardElement(')]
setup='''localStorage.removeItem('s4t-chart-copy-template-v1');function getBoardShortLink(){return 'fixture'};const board={name:'Sprint',members:[{id:'a',fullName:'Alex'},{id:'b',fullName:'Blair'},{id:'c',fullName:'Chris'}],lists:[],cards:[{id:'1',name:'(4) Work',idMembers:['a'],labels:[{id:'h',name:'Hotfix',color:'red'}]},{id:'2',name:'(2) Other',idMembers:['b'],labels:[]}]};function fetchBoardData(id,force,cb){setTimeout(()=>cb(null,board),5)};let copied='';Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async value=>{copied=value}}});let popup, pipCalls=0, fallbackCalls=0;function makePopup(){const frame=document.createElement('iframe');frame.style.cssText='width:420px;height:480px;border:0';document.body.append(frame);Object.defineProperty(frame.contentWindow.navigator,'clipboard',{configurable:true,value:{writeText:async value=>{copied=value}}});popup={document:frame.contentDocument,closed:false,focus(){this.focused=true},addEventListener(){},close(){this.closed=true;frame.remove()}};return popup}Object.defineProperty(window,'documentPictureInPicture',{configurable:true,value:{requestWindow:async()=>{pipCalls++;return makePopup()}}});window.open=()=>{fallbackCalls++;return makePopup()};'''
tests='''(async()=>{const wait=ms=>new Promise(r=>setTimeout(r,ms)),errors=[],check=(v,m)=>{if(!v)errors.push(m)},el=s=>document.querySelector(s);try{s4tOpenCharts();await wait(50);check(document.querySelectorAll('.s4t-chart-slice').length===2,'two developer slices');check(el('.s4t-chart-dialog').getBoundingClientRect().width>el('.s4t-chart-dialog').getBoundingClientRect().height,'wider popup');check(el('.s4t-chart-legend').getBoundingClientRect().left>el('.s4t-chart-canvas').getBoundingClientRect().left,'legend on right');el('[data-chart-copy]').click();await wait(5);check(copied==='Alex — 4 points\\nBlair — 2 points','copies developer points only');el('.s4t-chart-legend button').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));await wait(5);check(copied==='Alex — 4 points','double click copies visible row');el('[data-copy-options]').click();check(!el('.s4t-chart-copy-editor').hidden,'format dropdown opens');check(el('.s4t-copy-editable').textContent.includes('Editable'),'editable badge');check(!el('.s4t-chart-copy-editor').textContent.includes('Saved locally'),'no saved location text');check(el('.s4t-copy-example').textContent.startsWith('e.g. '),'example line');async function dragField(key,targetKey,after){const source=el('[data-copy-field="'+key+'"]'),target=el('[data-copy-field="'+targetKey+'"]'),data=new DataTransfer(),rect=target.getBoundingClientRect();source.dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer:data}));target.dispatchEvent(new DragEvent('dragover',{bubbles:true,cancelable:true,dataTransfer:data,clientX:after?rect.right-1:rect.left+1}));check(target.dataset.dropEdge===(after?'after':'before'),'drop insertion cue');target.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:data}));source.dispatchEvent(new DragEvent('dragend',{bubbles:true,dataTransfer:data}));await wait(5);}await dragField('points','name',false);check(el('.s4t-chart-copy-fields').firstElementChild.dataset.copyField==='points','drag reorder applied');await dragField('points','name',true);check(el('.s4t-chart-copy-fields').firstElementChild.dataset.copyField==='name','reverse drag applied');el('[data-copy-field="cards"]').click();check(el('[data-copy-field="cards"]').getAttribute('aria-checked')==='true','field selected');el('[data-copy-field="cards"]').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',altKey:true,bubbles:true}));check(JSON.parse(localStorage.getItem('s4t-chart-copy-template-v1')).dev[1].key==='cards','reordered template persisted');el('[data-chart-copy]').click();await wait(5);check(copied==='Alex — 1 cards · 4 points\\nBlair — 1 cards · 2 points','selected fields copied in order');el('[data-copy-options]').click();el('[data-copy-options]').click();check(el('.s4t-chart-copy-fields').children[1].dataset.copyField==='cards','saved order restored');el('[data-copy-field="cards"]').click();el('[data-copy-options]').click();const slice=el('.s4t-chart-slice');check(el('.s4t-chart-percentage').style.opacity==='0','percentage hidden initially');slice.dispatchEvent(new MouseEvent('mouseenter'));check(slice.style.transform.includes('translate'),'hover peeks out');check(el('.s4t-chart-percentage').style.opacity==='1','hover shows percentage');slice.dispatchEvent(new MouseEvent('mouseleave'));check(el('.s4t-chart-percentage').style.opacity==='0','percentage hides on leave');slice.click?.();slice.dispatchEvent(new MouseEvent('click'));check(slice.getAttribute('aria-pressed')==='true','slice selection pinned');el('[data-chart-tab="labels"]').click();check(el('.s4t-chart-note').textContent.includes('Multi-label'),'overlap explained');check(el('.s4t-chart-legend').textContent.includes('Hotfix'),'label names shown');check(el('.s4t-chart-slice').getAttribute('fill').includes('accent-red'),'label uses board red color');el('[data-chart-copy]').click();await wait(5);check(copied.includes('Hotfix — 1 cards · 50.0%'),'copies label percentages only');el('[data-chart-popout]').click();await wait(30);check(pipCalls===1 && fallbackCalls===0,'prefers floating PiP');check(popup.document.querySelector('[data-chart-tab="labels"]').getAttribute('aria-selected')==='true','popout retains selected tab');check(popup.document.querySelectorAll('.s4t-chart-slice').length===2,'popout rendered chart');check(!el('.s4t-chart-overlay'),'peek automatically closes source');popup.document.querySelector('[data-chart-copy]').click();await wait(5);check(copied.includes('Hotfix — 1 cards · 50.0%'),'peek copy works');check(!popup.closed,'closing source preserves peek');const detached=popup.document.querySelector('.s4t-chart-dialog');check(detached.classList.contains('s4t-chart-detached'),'detached layout');check(!detached.querySelector('.s4t-chart-note') && !detached.querySelector('.s4t-chart-legend'),'peek has no footer or legend');const paths=detached.querySelectorAll('.s4t-chart-slice');paths[0].focus();paths[0].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));check(popup.document.activeElement===paths[1],'right arrow moves to next slice');paths[1].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true}));check(popup.document.activeElement===paths[0],'down arrow wraps');paths[0].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',bubbles:true}));check(popup.document.activeElement===paths[1],'left arrow wraps');paths[1].dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));check(paths[1].getAttribute('aria-pressed')==='true','keyboard pins slice');check(detached.querySelectorAll('.s4t-chart-percentage').length===2,'readable percentages');check(detached.querySelector('.s4t-chart-canvas').getBoundingClientRect().height>350,'peek chart uses available height');check(Math.abs(detached.getBoundingClientRect().width-420)<2,'fills window width');check(Math.abs(detached.getBoundingClientRect().height-480)<2,'fills window height');popup.document.querySelector('[data-chart-tab="dev"]').click();check(popup.document.querySelector('[data-chart-tab="dev"]').getAttribute('aria-selected')==='true','peek interactive after source closes');popup.document.querySelector('[data-chart-refresh]').click();await wait(30);check(popup.document.querySelectorAll('.s4t-chart-slice').length===2,'peek refresh independent');s4tOpenCharts();await wait(30);el('[data-chart-popout]').click();check(pipCalls===1 && popup.focused,'existing peek reused');window.s4tPreferences={enabled:()=>false};document.dispatchEvent(new Event('s4t-preferences-changed'));check(popup.closed,'disabling charts closes peek window');s4tOpenCharts();check(!el('.s4t-chart-overlay'),'disabled charts cannot open');window.s4tPreferences.enabled=()=>true;s4tOpenCharts();await wait(50);check(!!el('.s4t-chart-overlay'),'charts can be enabled again');el('[data-chart-close]').click();check(popup.closed && !el('.s4t-chart-overlay'),'reusing peek closes source');s4tOpenCharts();await wait(30);window.documentPictureInPicture.requestWindow=async()=>{throw Error('Unavailable')};el('[data-chart-popout]').click();await wait(30);check(fallbackCalls===1,'small popup fallback');check(!el('.s4t-chart-overlay')&&!popup.closed,'fallback closes source and stays open');window.s4tPreferences={enabled:()=>false};document.dispatchEvent(new Event('s4t-preferences-changed'));check(popup.closed,'disabling charts closes peek window');s4tOpenCharts();check(!el('.s4t-chart-overlay'),'disabled charts cannot open');window.s4tPreferences.enabled=()=>true;s4tOpenCharts();await wait(50);check(!!el('.s4t-chart-overlay'),'charts can be enabled again');el('[data-chart-close]').click();}catch(e){errors.push(e.stack)}el('#result').textContent=errors.length?'FAIL: '+errors.join('; '):'PASS: pie slices, hover, selection, tabs, popout and close';})();'''
Path('/tmp/s4t-charts-ui.html').write_text('<html><body><pre id="result">RUNNING</pre><script>'+setup+helpers+(root/'charts.js').read_text()+tests+'</script></body></html>')
